INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p47277-econ403', 'stk-user462', 'ECON 403', 'info', '{"desc": "انا عندي ECON403 هذا السمستر مع مسيح … اول كلاس يقول لنا لا احد يحذف و الكورس سهل و هذي ماده اختياريه و الخ و الخ\n\nيوم جاء الميجر عطانا نوت من FIN301 و بسبب هذا النوت الافرج صار بحدود 70 😦 و قام يتأسف … يقول على باله اننا راح نبدع لأنه سهل و الخ … المشكله اللي صارت هي ان النوت جاء منه ملتبيل شويز و كان السؤال هو سبب التخبيص …\n\nالحين يقول انه راح يعطينا مسائل (يعني كأنها فيزياء) على قد عقول الانجينيرينق :D… و يقول اللي يجيب تحت 90 بالميجر الثاني يعرف ان الخطأ من الطالب نفسه مو منه…\nويقول الفاينل اسهل شئ لأن الاسئله تتكرر …\n\nو على حد علمي ما احد يطلع تحت +C من عنده … يعني اذا انت جايب الاعياد كلها تطلع بـ +C و اذا تذاكر شوي تطلع بـ B و طالع… و اذا تبغى تدفر فالـ +A قدامك\n\nالمشكله السمستر الجاي راح يدرس بس ECON410 على حد علمي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-403/34460/2", "user": "user462", "ts": 1081843849000, "tid": 34460, "pn": 2}}', 1081843849000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
